mapper.select:
SELECT TO_CHAR(count_time, #{timeType}) AS date, COALESCE(SUM(energy_consumption), 0) AS water FROM bbx_meter_auto_record_count WHERE count_time >= #{minDay} AND count_time <= #{maxDay} AND energy_consumption IS NOT NULL AND energy_consumption >= 0 AND deleted = 1
and tenant_id =#{tenantId}
AND device_id in
#{deviceId}
GROUP BY TO_CHAR(count_time, #{timeType})

WITH -- 1. 获取目标子支路（直接下级） target_branches AS ( SELECT id, branch_name FROM bbx_energy_branch WHERE branch_type = #{branchType} AND tenant_id = #{tenantId} AND deleted=1 AND (
parent_id IS NULL
parent_id = #{branchId}
) ), -- 2. 计算每个支路的总能耗（通过关联设备与自动抄表记录） branch_energy AS ( SELECT bd.branch_id, SUM(COALESCE(ac.energy_consumption, 0)) AS total_energy FROM bbx_branch_device bd LEFT JOIN bbx_meter_auto_record_count ac ON bd.device_id = ac.device_id AND ac.count_time BETWEEN #{startTime} AND #{endTime} AND ac.tenant_id = #{tenantId} WHERE bd.branch_id IN (SELECT id FROM target_branches) AND bd.tenant_id = #{tenantId} GROUP BY bd.branch_id ), -- 3. 判断是否有下级支路 branch_has_children AS ( SELECT b.parent_id, CASE WHEN COUNT(*) > 0 THEN 1 ELSE 0 END AS has_children FROM bbx_energy_branch b WHERE b.parent_id IN (SELECT id FROM target_branches) AND b.branch_type = #{branchType} AND b.tenant_id = #{tenantId} AND b.deleted = 1 GROUP BY b.parent_id ) -- 4. 最终结果 SELECT tb.id, tb.branch_name AS branchName, COALESCE(be.total_energy, 0) AS water, -- 用水量（总能耗） COALESCE(bhc.has_children, 0) AS hasChildren FROM target_branches tb LEFT JOIN branch_energy be ON tb.id = be.branch_id LEFT JOIN branch_has_children bhc ON tb.id = bhc.parent_id ORDER BY tb.id

SELECT device_id AS deviceId, ROUND(SUM(COALESCE(energy_consumption, 0)), 2) AS value FROM bbx_meter_auto_record_count WHERE device_id IN
#{id}
AND count_time BETWEEN #{startTime} AND #{endTime} AND deleted = 1 AND tenant_id = #{tenantId} GROUP BY device_id ORDER BY value DESC LIMIT 5
